ext('c12_pol_ch9',[
C("🗳️","पहले आम चुनाव की ख़ासियतें",["सन उन्नीस सौ इक्यावन-बावन","सार्वभौमिक वयस्क मताधिकार","निरक्षरों के लिए चिह्न","चुनाव आयोग की भूमिका"],"भारत में पहला आम चुनाव सन उन्नीस सौ इक्यावन-बावन में हुआ। इसमें सभी वयस्क नागरिकों को बिना भेदभाव के मतदान का अधिकार दिया गया। बहुत से लोग पढ़ना नहीं जानते थे, इसलिए हर दल को एक चुनाव चिह्न दिया गया। इतने बड़े चुनाव का संचालन चुनाव आयोग ने कुशलता से किया।"),
C("🏛️","कांग्रेस के प्रभुत्व के कारण",["स्वतंत्रता आंदोलन की विरासत","देशभर में संगठन","अलग-अलग विचारों को जगह","नेहरू का लोकप्रिय नेतृत्व"],"पहले तीन आम चुनावों में कांग्रेस को बड़ी जीत मिली। इसके पीछे उसकी स्वतंत्रता आंदोलन की विरासत थी। देश भर में उसका मज़बूत संगठन था। कांग्रेस में अलग-अलग विचारों के लोग थे, इसलिए वह एक व्यापक मंच की तरह थी। जवाहरलाल नेहरू के लोकप्रिय नेतृत्व ने भी उसे बढ़त दिलाई।"),
C("🌿","विपक्षी दलों का उदय",["समाजवादी दल","भारतीय जनसंघ","स्वतंत्र पार्टी","कम्युनिस्ट पार्टी"],"इस दौर में भी कई विपक्षी दल सक्रिय थे। समाजवादी दल, भारतीय जनसंघ, स्वतंत्र पार्टी और भारतीय कम्युनिस्ट पार्टी जैसे दलों ने अलग-अलग विचारों को सामने रखा। संसद में उनकी संख्या कम थी, फिर भी उन्होंने सरकार की नीतियों की आलोचना करके लोकतंत्र को मज़बूती दी।"),
C("🐘","केरल की पहली गैर-कांग्रेसी सरकार",["सन उन्नीस सौ सत्तावन","कम्युनिस्ट पार्टी की जीत","भूमि सुधार जैसी नीतियाँ","सन उन्नीस सौ उनसठ में बर्खास्त"],"सन उन्नीस सौ सत्तावन के चुनाव में केरल में कम्युनिस्ट पार्टी की सरकार बनी। यह दुनिया में लोकतांत्रिक चुनाव से बनी पहली कम्युनिस्ट सरकार मानी जाती है। इस सरकार ने भूमि सुधार और शिक्षा के कुछ कदम उठाए, पर सन उन्नीस सौ उनसठ में केंद्र ने उसे अनुच्छेद तीन सौ छप्पन का प्रयोग करके बर्खास्त कर दिया।"),
],5)
ext('c12_pol_ch10',[
C("📈","पंचवर्षीय योजनाओं की दिशा",["पहली योजना: कृषि","दूसरी योजना: उद्योग","तीसरी योजना: आत्मनिर्भरता","योजना आयोग की भूमिका"],"योजना आयोग की स्थापना सन उन्नीस सौ पचास में हुई। पहली पंचवर्षीय योजना में कृषि पर ज़ोर दिया गया। दूसरी योजना में भारी उद्योगों को प्राथमिकता मिली, जिसका आधार पी. सी. महालनोबिस का मॉडल था। तीसरी योजना में आत्मनिर्भरता पर ध्यान दिया गया। पर इसी बीच चीन और पाकिस्तान के युद्धों से योजनाओं पर असर पड़ा।"),
C("🏭","सार्वजनिक क्षेत्र की भूमिका",["इस्पात संयंत्र","बाँध और बिजली परियोजनाएँ","मिश्रित अर्थव्यवस्था","निजी क्षेत्र भी साथ"],"भारत ने मिश्रित अर्थव्यवस्था का रास्ता चुना, जिसमें सार्वजनिक और निजी दोनों क्षेत्र काम करते थे। भारी उद्योग, जैसे इस्पात संयंत्र और बाँध, सार्वजनिक क्षेत्र में लगाए गए। निजी क्षेत्र को भी काम करने की जगह दी गई। लेकिन अधिक नियमन से कई बार काम की गति धीमी रही।"),
C("🥛","श्वेत क्रांति",["वर्गीज़ कुरियन का योगदान","अमूल की सहकारी व्यवस्था","दुग्ध उत्पादन में वृद्धि","किसानों को सीधी आय"],"श्वेत क्रांति दूध उत्पादन बढ़ाने की मुहिम थी। इसका नेतृत्व वर्गीज़ कुरियन ने किया। गुजरात के आनंद में अमूल जैसी सहकारी संस्था बनी, जिसने दूध उत्पादकों को सीधे बाज़ार से जोड़ा। इससे दूध उत्पादन बहुत बढ़ा और छोटे किसानों की आय में भी सुधार आया।"),
C("🧐","विकास योजनाओं की आलोचना",["असमान लाभ","नौकरशाही और लाल फ़ीताशाही","गरीबी पर कम असर","लक्ष्य पूरे न होना"],"योजनाओं की कई आलोचनाएँ भी हुईं। कहा गया कि उनका लाभ सभी तक समान रूप से नहीं पहुँचा। नौकरशाही और लाल फ़ीताशाही से काम में देरी हुई। गरीबी पर भी अपेक्षित असर नहीं दिखा, और कई लक्ष्य पूरे नहीं हो पाए। इन्हीं अनुभवों से आगे चलकर नीतियों में बदलाव आए।"),
],5)
ext('c12_pol_ch11',[
C("🤝","गुटनिरपेक्ष आंदोलन",["शीत युद्ध में किसी खेमे में नहीं","नेहरू, नासिर, टीटो","स्वतंत्र निर्णय का अधिकार","विकासशील देशों की आवाज़"],"शीत युद्ध के समय भारत ने किसी भी गुट में शामिल न होने की नीति अपनाई, जिसे गुटनिरपेक्षता कहा गया। नेहरू, मिस्र के नासिर और यूगोस्लाविया के टीटो इसके प्रमुख नेता थे। इसका अर्थ था अपने फ़ैसले स्वतंत्र रूप से लेना और विकासशील देशों की आवाज़ को मज़बूत करना।"),
C("🏔️","सन बासठ का भारत-चीन युद्ध",["सीमा विवाद","चीन का आक्रमण","भारत को झटका","रक्षा तैयारी पर ध्यान"],"सन उन्नीस सौ बासठ में चीन ने भारत की सीमा पर आक्रमण किया। इस युद्ध में भारत को पराजय का सामना करना पड़ा। इससे भारत की विदेश नीति और रक्षा नीति पर गहरा असर पड़ा। उसके बाद भारत ने अपनी सेना की तैयारी पर ज़्यादा ध्यान देना शुरू किया।"),
C("⚔️","पाकिस्तान के साथ युद्ध",["सन पैंसठ का युद्ध","सन इकहत्तर का युद्ध","बांग्लादेश का जन्म","शिमला समझौता"],"भारत और पाकिस्तान के बीच सन उन्नीस सौ पैंसठ में युद्ध हुआ। सन उन्नीस सौ इकहत्तर के युद्ध के बाद पूर्वी पाकिस्तान अलग होकर बांग्लादेश बना। इसके बाद दोनों देशों के बीच शिमला समझौता हुआ, जिसमें आपसी विवाद बातचीत से सुलझाने की बात कही गई।"),
C("💥","परमाणु परीक्षण",["सन उन्नीस सौ चौहत्तर","सन उन्नीस सौ अट्ठानवे","न्यूनतम विश्वसनीय अवरोध","पहले इस्तेमाल न करने की नीति"],"भारत ने पहला परमाणु परीक्षण सन उन्नीस सौ चौहत्तर में किया और फिर सन उन्नीस सौ अट्ठानवे में पोखरण में पाँच परीक्षण किए। भारत का कहना है कि उसके परमाणु हथियार केवल न्यूनतम विश्वसनीय अवरोध के लिए हैं। भारत ने घोषणा की है कि वह पहले परमाणु हथियार का इस्तेमाल नहीं करेगा।"),
],5)
ext('c12_pol_ch12',[
C("👩","इंदिरा गांधी का उदय",["शास्त्री जी के बाद","सन उन्नीस सौ छियासठ में प्रधानमंत्री","कांग्रेस में सिंडिकेट से टकराव","बैंकों का राष्ट्रीयकरण"],"लाल बहादुर शास्त्री के निधन के बाद इंदिरा गांधी सन उन्नीस सौ छियासठ में प्रधानमंत्री बनीं। शुरू में कांग्रेस के वरिष्ठ नेताओं के एक समूह, जिसे सिंडिकेट कहा जाता था, से उनका टकराव हुआ। सन उन्नीस सौ उनहत्तर में उन्होंने चौदह बड़े बैंकों का राष्ट्रीयकरण किया, जो उनके समाजवादी रुख का संकेत था।"),
C("🗳️","सन सड़सठ के चुनाव का असर",["कई राज्यों में कांग्रेस हारी","संयुक्त विधायक दल सरकारें","दलबदल की राजनीति","केंद्र में पतली बहुमत"],"सन उन्नीस सौ सड़सठ के चुनाव में कांग्रेस की सीटें बहुत कम हुईं। कई राज्यों में कांग्रेस हार गई और विपक्षी दलों ने मिलकर संयुक्त विधायक दल की सरकारें बनाईं। इसी दौर में दलबदल की राजनीति भी बढ़ी, जिससे सरकारें अस्थिर हो गईं। केंद्र में कांग्रेस को बहुत कम बहुमत मिला।"),
C("🌾","गरीबी हटाओ का नारा",["सन इकहत्तर के चुनाव","इंदिरा गांधी की लोकप्रियता","बड़े बहुमत की जीत","बाद में निराशा"],"सन उन्नीस सौ इकहत्तर के चुनाव में इंदिरा गांधी ने गरीबी हटाओ का नारा दिया। इससे उन्हें गरीबों और वंचितों का बड़ा समर्थन मिला और कांग्रेस ने भारी बहुमत से जीत हासिल की। पर नारे के अनुसार गरीबी बहुत कम घटी, जिससे बाद में लोगों में निराशा भी बढ़ी।"),
C("⚖️","कांग्रेस की पुनर्स्थापना",["कांग्रेस का विभाजन","नई कांग्रेस का बड़ा बहुमत","सरकार का केंद्रीकरण","विपक्ष कमज़ोर"],"सन उन्नीस सौ उनहत्तर में कांग्रेस दो भागों में बँट गई। इंदिरा गांधी के गुट ने सन इकहत्तर में बड़ी जीत हासिल की और कांग्रेस की सत्ता फिर मज़बूत हुई। पर इससे पार्टी के भीतर और सरकार में शक्ति एक नेता के हाथ में सिमटने लगी, जो आगे चलकर संकट का कारण बनी।"),
],5)
ext('c12_pol_ch13',[
C("🌆","गुजरात और बिहार आंदोलन",["महँगाई और भ्रष्टाचार","छात्र आंदोलन","जयप्रकाश नारायण का नेतृत्व","संपूर्ण क्रांति का नारा"],"सन उन्नीस सौ चौहत्तर में गुजरात में महँगाई और भ्रष्टाचार के विरुद्ध छात्रों ने आंदोलन चलाया। बिहार में भी छात्र आंदोलन उठा, जिसका नेतृत्व जयप्रकाश नारायण ने किया। उन्होंने संपूर्ण क्रांति का नारा दिया। यह आंदोलन धीरे-धीरे पूरे देश में फैलने लगा और सरकार पर दबाव बढ़ा।"),
C("⚖️","इलाहाबाद उच्च न्यायालय का फ़ैसला",["सन उन्नीस सौ पचहत्तर","इंदिरा गांधी का चुनाव रद्द","सर्वोच्च न्यायालय में अपील","आपातकाल की ओर"],"सन उन्नीस सौ पचहत्तर में इलाहाबाद उच्च न्यायालय ने इंदिरा गांधी का चुनाव रद्द कर दिया, क्योंकि उन पर चुनाव में सरकारी तंत्र के गलत उपयोग का आरोप सिद्ध हुआ। विपक्ष ने उनके इस्तीफ़े की माँग की। इसी राजनीतिक संकट के बीच पच्चीस जून को आपातकाल की घोषणा कर दी गई।"),
C("📰","आपातकाल के दौरान",["नागरिक अधिकार निलंबित","प्रेस पर सेंसरशिप","विपक्षी नेताओं की गिरफ़्तारी","बीस सूत्री कार्यक्रम"],"आपातकाल में नागरिकों के मौलिक अधिकार निलंबित कर दिए गए। समाचार पत्रों पर सेंसरशिप लगाई गई। जयप्रकाश नारायण समेत कई विपक्षी नेताओं को जेल में डाल दिया गया। सरकार ने बीस सूत्री कार्यक्रम घोषित किया, पर ज़बरदस्ती नसबंदी जैसी ज्यादतियों से लोगों में गहरा गुस्सा फैला।"),
C("🗳️","सन सतहत्तर की जीत",["चुनाव की घोषणा","जनता पार्टी का गठन","पहली बार केंद्र में कांग्रेस हारी","मोरारजी देसाई प्रधानमंत्री"],"सन उन्नीस सौ सतहत्तर में चुनाव की घोषणा हुई। विपक्ष के कई दल मिलकर जनता पार्टी बने। चुनाव में कांग्रेस की भारी हार हुई और इंदिरा गांधी भी अपनी सीट हार गईं। पहली बार केंद्र में गैर-कांग्रेसी सरकार बनी, जिसके प्रधानमंत्री मोरारजी देसाई थे। इससे भारत के लोकतंत्र की ताक़त सामने आई।"),
],5)
ext('c12_pol_ch14',[
C("🏔️","जम्मू-कश्मीर का इतिहास",["सन उन्नीस सौ सैंतालीस के बाद विलय","अनुच्छेद तीन सौ सत्तर","राज्य की विशेष स्थिति","सन दो हज़ार उन्नीस का बदलाव"],"जम्मू-कश्मीर रियासत का भारत में विलय सन उन्नीस सौ सैंतालीस में हुआ। संविधान के अनुच्छेद तीन सौ सत्तर के तहत उसे विशेष दर्जा दिया गया था। लंबे समय तक वहाँ अलगाववाद और आतंकवाद की समस्या रही। सन दो हज़ार उन्नीस में अनुच्छेद तीन सौ सत्तर के अधिकांश प्रावधान समाप्त कर दिए गए और राज्य को दो केंद्र शासित प्रदेशों में बाँटा गया।"),
C("🌄","पंजाब की समस्या",["अधिक स्वायत्तता की माँग","आनंदपुर साहिब प्रस्ताव","सन उन्नीस सौ चौरासी की घटनाएँ","राजीव-लोंगोवाल समझौता"],"पंजाब में अकाली दल ने अधिक स्वायत्तता की माँग की, जिसे आनंदपुर साहिब प्रस्ताव में रखा गया। बाद में कुछ गुटों ने हिंसा का रास्ता अपना लिया। सन उन्नीस सौ चौरासी की दुखद घटनाओं के बाद राजीव गांधी और संत हरचंद सिंह लोंगोवाल के बीच समझौता हुआ, जिसके बाद धीरे-धीरे शांति लौटी।"),
C("🌿","पूर्वोत्तर के आंदोलन",["नागालैंड की माँग","मिज़ोरम में समझौता","असम आंदोलन","बाहरी लोगों का मुद्दा"],"पूर्वोत्तर राज्यों में अलग-अलग कारणों से आंदोलन उठे। नागालैंड में अलगाव की माँग हुई। मिज़ोरम में सन उन्नीस सौ छियासी में शांति समझौता हुआ और वहाँ शांति आई। असम में बाहरी लोगों के मुद्दे पर आंदोलन हुआ, जिसका अंत असम समझौते से हुआ।"),
C("🗣️","भाषा और क्षेत्रीय पहचान",["भाषा के आधार पर राज्य","द्रविड़ आंदोलन","क्षेत्रीय दलों का उदय","संघवाद की मज़बूती"],"भारत में भाषा और क्षेत्रीय पहचान ने कई राज्यों की राजनीति को आकार दिया। तमिलनाडु का द्रविड़ आंदोलन इसका उदाहरण है। इन आंदोलनों से क्षेत्रीय दल उभरे। भारत ने इनसे निपटने के लिए अलग-अलग क्षेत्रों की आकांक्षाओं को स्वीकार किया और संघीय ढाँचे को अपनाया।"),
],5)
ext('c12_pol_ch15',[
C("📜","मंडल आयोग की सिफ़ारिशें",["अन्य पिछड़ा वर्ग","सत्ताईस प्रतिशत आरक्षण","सन उन्नीस सौ नब्बे में लागू","देश भर में विरोध और समर्थन"],"मंडल आयोग ने अन्य पिछड़े वर्गों के लिए सरकारी नौकरियों में सत्ताईस प्रतिशत आरक्षण की सिफ़ारिश की थी। सन उन्नीस सौ नब्बे में वी. पी. सिंह सरकार ने इसे लागू करने की घोषणा की। इस पर देश भर में विरोध और समर्थन दोनों हुए। इससे पिछड़े वर्गों की राजनीति तेज़ी से उभरी।"),
C("🕌","अयोध्या विवाद",["बाबरी मस्जिद और राम मंदिर","सन उन्नीस सौ बानवे की घटना","सांप्रदायिक तनाव","न्यायालय का अंतिम फ़ैसला"],"अयोध्या में बाबरी मस्जिद और राम जन्मभूमि का विवाद लंबे समय तक चला। सन उन्नीस सौ बानवे में मस्जिद ढहा दी गई, जिसके बाद देश में सांप्रदायिक तनाव बढ़ा। यह मामला लंबे समय तक न्यायालय में चला। अंत में सर्वोच्च न्यायालय ने सन दो हज़ार उन्नीस में अपना अंतिम फ़ैसला दिया।"),
C("🤝","गठबंधन राजनीति का दौर",["सन उन्नीस सौ नवासी के बाद","कई दलों की साझा सरकारें","क्षेत्रीय दलों की भूमिका","राजनीतिक स्थिरता की चुनौती"],"सन उन्नीस सौ नवासी के बाद केंद्र में किसी एक दल को स्पष्ट बहुमत मिलना कठिन हो गया और गठबंधन सरकारों का दौर शुरू हुआ। क्षेत्रीय दलों की भूमिका बढ़ गई। राष्ट्रीय जनतांत्रिक गठबंधन और संयुक्त प्रगतिशील गठबंधन जैसी सरकारें बनीं। इससे राजनीति में विविध आवाज़ों को जगह मिली, पर स्थिरता की चुनौती भी आई।"),
C("🧮","आर्थिक सुधार और राजनीति",["सन उन्नीस सौ इक्यानवे के सुधार","उदारीकरण और निजीकरण","असमानता की बहस","नई आर्थिक नीतियों का राजनीतिक असर"],"सन उन्नीस सौ इक्यानवे में भारत ने नई आर्थिक नीति अपनाई, जिसमें उदारीकरण, निजीकरण और वैश्वीकरण पर ज़ोर था। इन सुधारों से आर्थिक वृद्धि बढ़ी, पर असमानता की बहस भी तेज़ हुई। इस बात पर राजनीतिक दलों में सहमति बनी कि सुधार जारी रहें, चाहे सरकार किसी भी दल की हो।"),
],5)
